#include "audio/WorldAudioDirector.hpp"
#include "core/Saturating.hpp"
#include <algorithm>
namespace elysium::audio {AudioDirectorFrame WorldAudioDirector::update(const AudioWorldSnapshot&s,const AudioDirectorPolicy&p) {AudioDirectorFrame o;auto add=[&](AudioLayerKind k,double raw,std::uint64_t palette,bool continuous,VisualTwinKind* twin=nullptr){double v=elysium::safe::finiteClamp(raw,0.0,1.0);auto&st=state_[k];if(!st.active&&v>=p.engageThreshold&&s.tick>=st.lastChangeTick+p.cooldownTicks){st.active=true;st.lastChangeTick=s.tick;}else if(st.active&&v<=p.releaseThreshold&&s.tick>=st.lastChangeTick+p.cooldownTicks){st.active=false;st.lastChangeTick=s.tick;}if(st.active){o.layers.push_back({k,palette,v,s.dialogueActive?elysium::safe::finiteClamp(p.dialogueDuck,0.0,1.0):1.0,continuous});if(twin)o.visualTwins.push_back({*twin,v});}};VisualTwinKind pressure=VisualTwinKind::PressureWarning,rad=VisualTwinKind::RadiationWarning,hazard=VisualTwinKind::HazardIndicator,reg=VisualTwinKind::RegisterActionWarning;add(AudioLayerKind::Wind,s.wind,s.factionPaletteId,true);add(AudioLayerKind::Acid,s.acid,s.factionPaletteId,true,&hazard);add(AudioLayerKind::Radiation,s.radiation,s.factionPaletteId,true,&rad);add(AudioLayerKind::PressureCreak,s.pressureStress,s.factionPaletteId,true,&pressure);add(s.factionPaletteId?AudioLayerKind::ImperialMachinery:AudioLayerKind::FrontierActivity,.35,s.factionPaletteId,true);double suspicion=elysium::safe::finiteClamp(s.suspicion/100.0,0.0,1.0);add(AudioLayerKind::ExplorationMusic,s.registerActionActive?0.0:(1.0-suspicion),s.factionPaletteId,true);add(AudioLayerKind::SuspicionMusic,s.registerActionActive?0.0:suspicion,s.factionPaletteId,true);add(AudioLayerKind::RegisterActionMusic,s.registerActionActive?1.0:0.0,s.factionPaletteId,true,&reg);return o;}}
